public class SelfLinkProbe62 {
    private static Map<String, String> knownIds;
    private static List<Object> errorCatalog;
    private static Map<String, Integer> errorKeys;

    private static String normalize(String text) {
        if (text == null) return null;
        for (String known : knownIds.keySet()) {
            text = text.replace(known, knownIds.get(known));
            text = text.replace(known.substring(0, 15), knownIds.get(known));
        }
        return text;
    }
    private static String parentLabel(Id value) {
        if (value == null) return null;
        String key = String.valueOf(value);
        return knownIds.containsKey(key) ? knownIds.get(key) : 'other-real-id';
    }
    private static Integer recordError(String caseName, String mode, String code, List<String> fields, String message) {
        System.debug(LoggingLevel.ERROR, 'LINK_RAW|' + JSON.serialize(new Map<String, Object>{
            'case' => caseName, 'mode' => mode, 'code' => code, 'fields' => fields, 'message' => message
        }));
        List<Object> error = new List<Object>{code, fields, normalize(message)};
        String key = JSON.serialize(error);
        if (!errorKeys.containsKey(key)) {
            errorKeys.put(key, errorCatalog.size());
            errorCatalog.add(error);
        }
        return errorKeys.get(key);
    }
    private static Map<String, Object> insertCase(String caseName, Boolean allOrNone, Id missing, Id existing, Id deleted) {
        LinkNode__c caller = new LinkNode__c();
        if (caseName != 'missingNameParent' && caseName != 'missingNameOnly') caller.Name = caseName;
        if (caseName == 'missingParent' || caseName == 'missingNameParent') caller.Parent__c = missing;
        if (caseName == 'validParent') caller.Parent__c = existing;
        if (caseName == 'nullParent') caller.Parent__c = null;
        if (caseName == 'deletedParent') caller.Parent__c = deleted;
        String mode = allOrNone ? 'throwing' : 'partial';
        Map<String, Object> row = new Map<String, Object>();
        List<Object> errors = new List<Object>();
        try {
            List<SObject> inputs = new List<SObject>{caller};
            List<Database.SaveResult> results = Database.insert(inputs, allOrNone, AccessLevel.SYSTEM_MODE);
            row.put('success', results[0].isSuccess());
            for (Database.Error error : results[0].getErrors()) {
                errors.add(new List<Object>{0, recordError(caseName, mode, String.valueOf(error.getStatusCode()), error.getFields(), error.getMessage())});
            }
        } catch (DmlException error) {
            row.put('success', false);
            row.put('exceptionType', error.getTypeName());
            System.debug(LoggingLevel.ERROR, 'LINK_RAW|' + JSON.serialize(new Map<String, Object>{
                'case' => caseName, 'mode' => mode, 'exceptionMessage' => error.getMessage()
            }));
            row.put('exceptionMessage', normalize(error.getMessage()));
            for (Integer index = 0; index < error.getNumDml(); index++) {
                errors.add(new List<Object>{error.getDmlIndex(index), recordError(caseName, mode, String.valueOf(error.getDmlType(index)), error.getDmlFieldNames(index), error.getDmlMessage(index))});
            }
        } catch (Exception error) {
            row.put('success', false);
            row.put('exceptionType', error.getTypeName());
            row.put('exceptionMessage', normalize(error.getMessage()));
        }
        row.put('errors', errors);
        row.put('idNull', caller.Id == null);
        row.put('callerName', caller.Name);
        row.put('callerParent', parentLabel(caller.Parent__c));
        Id inserted = caller.Id;
        row.put('storedCount', inserted == null ? 0 : [SELECT COUNT() FROM LinkNode__c WHERE Id = :inserted]);
        return row;
    }

    public static String observe() {
        knownIds = new Map<String, String>();
        errorCatalog = new List<Object>();
        errorKeys = new Map<String, Integer>();
        Map<String, Object> rows = new Map<String, Object>();
        Integer beforeCount = [SELECT COUNT() FROM LinkNode__c];
        Savepoint lifetime = Database.setSavepoint();
        try {
            LinkNode__c existing = new LinkNode__c(Name = 'existing-parent');
            LinkNode__c deleted = new LinkNode__c(Name = 'deleted-parent');
            insert new List<LinkNode__c>{existing, deleted};
            Id existingId = existing.Id;
            Id deletedId = deleted.Id;
            delete deleted;
            knownIds.put(String.valueOf(existingId), 'EXISTING');
            knownIds.put(String.valueOf(deletedId), 'DELETED');

            Savepoint allocation = Database.setSavepoint();
            LinkNode__c rolled = new LinkNode__c(Name = 'rolled');
            insert rolled;
            Id missing = rolled.Id;
            Database.rollback(allocation);
            knownIds.put(String.valueOf(missing), 'MISSING');
            rows.put('missingQueryCount', [SELECT COUNT() FROM LinkNode__c WHERE Id = :missing]);

            rows.put('existingQueryCount', [SELECT COUNT() FROM LinkNode__c WHERE Id = :existingId]);
            rows.put('deletedQueryCount', [SELECT COUNT() FROM LinkNode__c WHERE Id = :deletedId]);
            for (String caseName : new List<String>{'missingParent', 'missingNameParent', 'missingNameOnly', 'validParent', 'omittedParent', 'nullParent', 'deletedParent'}) {
                rows.put('partial/' + caseName, insertCase(caseName, false, missing, existingId, deletedId));
                rows.put('throwing/' + caseName, insertCase(caseName, true, missing, existingId, deletedId));
            }
            rows.put('errorCatalog', errorCatalog);
        } catch (Exception error) {
            rows.put('setupExceptionType', error.getTypeName());
            rows.put('setupExceptionMessage', normalize(error.getMessage()));
        } finally {
            Database.rollback(lifetime);
        }
        Integer afterCount = [SELECT COUNT() FROM LinkNode__c];
        rows.put('cleanupCountDelta', afterCount - beforeCount);
        return JSON.serialize(rows);
    }
}

